<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {listAuditEvents,getAuditEvent} from '../../api/audit'
import {createRecordPager} from '../../composables/recordPage.js'
import {offsetInstant} from '../../composables/restrictionForm.js'
import RecordFilters from '../RecordFilters.vue'
import RecordPageControls from '../RecordPageControls.vue'
import SButton from '../ui/SButton.vue'
import SBanner from '../ui/SBanner.vue'

const fields=[{key:'date_from',label:'起始校园日期',type:'date'},{key:'date_to',label:'截止校园日期',type:'date'},{key:'actor_id',label:'操作者账号编号'},{key:'object_type',label:'对象类型（精确）'},{key:'object_id',label:'对象标识（精确）'},{key:'action',label:'动作（精确）'}]
const actionNames={'user.create':'创建校园账号','user.update':'维护校园账号','reservation.create':'创建预约','reservation.cancel':'开始前取消预约','reservation.unused_end':'登记未使用结束','reservation.checkin':'座位码签到','reservation.correct_checkin':'核实补签','reservation.complete':'使用结束结算','reservation.admin_cancel':'资源管理取消','reservation.restriction_cancel':'限制取消预约','violation.register':'登记违规','violation.revoke':'撤销违规','restriction.create':'登记限制','restriction.apply':'执行限制善后','restriction.release':'解除单条限制','restriction.recalculate':'原批次重算','appeal.submit':'提交申诉','appeal.review':'审核申诉','review.create':'创建本人评价','review.update':'修改本人评价','review.reply':'管理回复评价','review.hide':'隐藏评价'}
const objectNames={user:'校园账号',room:'空间',seat:'座位',reservation:'预约',violation:'违规',restriction:'预约限制',appeal:'申诉',complaint:'求助与投诉',review:'使用评价',opening_schedule:'开放安排',seat_code:'座位码'}
const actionText=value=>actionNames[value]?`${actionNames[value]}（${value}）`:value
const objectText=value=>objectNames[value]?`${objectNames[value]}（${value}）`:value
function actorText(item){return item.actor_id===null?'系统':item.actor_username?`${item.actor_username}（账号#${item.actor_id}）`:`账号#${item.actor_id}（用户名未返回）`}
function validRedaction(value){return value&&['omitted_fields','truncated_values','redacted_values','omitted_items'].every(key=>Number.isSafeInteger(value[key])&&value[key]>=0)&&typeof value.notice==='string'&&!!value.notice}
function validMeta(value){return Number.isSafeInteger(value?.id)&&value.id>0&&(value.actor_id===null||Number.isSafeInteger(value.actor_id)&&value.actor_id>0)&&(value.actor_username===null||typeof value.actor_username==='string')&&validRedaction(value.redaction)&&typeof value.action==='string'&&typeof value.object_type==='string'&&typeof value.object_id==='string'&&typeof value.reason==='string'&&offsetInstant(value.occurred_at)!==null}
function safeObject(value){return value!==null&&typeof value==='object'&&!Array.isArray(value)}
function queryForAudit(query){const result={...query};if(result.actor_id!==undefined){const text=String(result.actor_id);if(!/^[1-9]\d*$/.test(text)||!Number.isSafeInteger(Number(text)))throw new Error('操作者账号编号须为正整数');result.actor_id=Number(text)}return result}
const pager=createRecordPager(async query=>{const {data}=await listAuditEvents(queryForAudit(query));if(!Array.isArray(data?.items)||!data.items.every(validMeta))throw new Error('审计列表元数据不完整，请重试');return{data}})
const {items,loading,error,filters,snapshot,snapshotQuery}=pager
const selected=ref(null),detail=ref(null),detailLoading=ref(false),detailError=ref('');let alive=true,sequence=0
async function open(id){if(!Number.isSafeInteger(id)||id<1){detailError.value='审计编号须为正整数';return}const ticket=++sequence;selected.value=id;detail.value=null;detailLoading.value=true;detailError.value='';try{const {data}=await getAuditEvent(id);if(!alive||ticket!==sequence)return;if(!validMeta(data)||data.id!==id||!safeObject(data.before_values)||!safeObject(data.after_values))throw new Error('审计详情安全投影不完整，请重试读取');detail.value=data}catch(e){if(alive&&ticket===sequence)detailError.value=e.message}finally{if(alive&&ticket===sequence)detailLoading.value=false}}
function pretty(value){return JSON.stringify(value,null,2)}
onMounted(()=>pager.refresh());onBeforeUnmount(()=>{alive=false;sequence++;pager.dispose()});defineExpose({refresh:pager.refresh})
</script>
<template><section class="audit-query"><section class="card"><h3>管理审计查询</h3><p>只读查看已保存的业务操作。筛选精确匹配，日期按校园时区；系统自动动作的操作者显示为系统。</p><RecordFilters v-model="filters" :fields="fields" :disabled="loading" @apply="pager.apply"/><SButton :disabled="loading" @click="pager.refresh()">刷新已应用条件</SButton><RecordPageControls :snapshot="snapshot" :query="snapshotQuery" :fields="fields" :disabled="loading" @page="pager.turn"/><SBanner v-if="error" type="error" :title="error"/><p v-if="loading" role="status">正在读取审计记录；下方保留上次成功快照。</p><p v-if="snapshot&&!items.length&&!loading&&!error">该次查询没有审计记录。</p><article v-for="item in items" :key="item.id"><h4>审计#{{item.id}} · {{actionText(item.action)}}</h4><p>{{actorText(item)}} · {{item.occurred_at}}</p><p>对象：{{objectText(item.object_type)}} / {{item.object_id}}</p><p class="audit-reason">公开操作理由：{{item.reason||'原记录未记公开理由'}}</p><p v-if="item.redaction.omitted_fields||item.redaction.truncated_values||item.redaction.redacted_values||item.redaction.omitted_items">此条元数据处理：省略字段{{item.redaction.omitted_fields}}、截断值{{item.redaction.truncated_values}}、脱敏值{{item.redaction.redacted_values}}、省略数组项{{item.redaction.omitted_items}}；不含前后快照计数。</p><SButton @click="open(item.id)">查看安全变更详情</SButton></article></section><section v-if="selected" class="card"><h3>审计#{{selected}}详情</h3><SButton :disabled="detailLoading" @click="open(selected)">重试/刷新此条</SButton><p v-if="detailLoading" role="status">正在鉴权读取该条安全投影…</p><SBanner v-if="detailError" type="error" :title="detailError"/><template v-if="detail"><h4>{{actionText(detail.action)}}</h4><p>{{actorText(detail)}} · {{detail.occurred_at}}</p><p>对象：{{objectText(detail.object_type)}} / {{detail.object_id}}</p><p class="audit-reason">公开操作理由：{{detail.reason||'原记录未记公开理由'}}</p><p>以下仅为允许展示的必要变更；部分字段已脱敏或省略，不能视为原始完整数据。需要管理私有材料时，请进入所属领域的管理详情另行核查。</p><p>省略字段：{{detail.redaction.omitted_fields}}；截断值：{{detail.redaction.truncated_values}}；脱敏值：{{detail.redaction.redacted_values}}；省略数组项：{{detail.redaction.omitted_items}}。</p><p v-if="detail.redaction?.notice">{{detail.redaction.notice}}</p><h4>操作前（安全投影）</h4><pre class="audit-values">{{pretty(detail.before_values)}}</pre><h4>操作后（安全投影）</h4><pre class="audit-values">{{pretty(detail.after_values)}}</pre></template></section></section></template>
<style scoped>.audit-query,.audit-query .card,.audit-query article{display:grid;gap:12px;min-width:0;overflow-wrap:anywhere}.audit-query article{border-top:1px solid var(--border);padding-top:12px}.audit-reason,.audit-values{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word}.audit-values{max-width:100%;font-size:var(--fs-caption);padding:12px;background:var(--surface-2);border-radius:var(--r-md)}</style>
